public class SimplexTableau_getSolution_TriageGen0Test {

    @Spy
    private SimplexTableau tableau;

    private static final String NEGATIVE_VAR_COLUMN_LABEL = "negative_var";
    private static final String RHS_COLUMN_LABEL = "rhs";

    @Before
    public void setUp() {
        MockitoAnnotations.initMocks(this);
    }

    /**
     * Helper to setup mock behavior for the protected methods of SimplexTableau
     */
    private void setupMockTableau(List<String> labels, int numDecisionVars, boolean restrictToNonNegative, double mostNegativeVal, int negativeVarColIdx, int negativeVarBasicRow) {
        doReturn(labels).when(tableau).getColumnLabels();
        doReturn(numDecisionVars).when(tableau).getOriginalNumDecisionVariables();
        doReturn(restrictToNonNegative).when(tableau).isRestrictToNonNegative(); // Assuming this getter exists based on usage

        // Mocking negative variable logic
        if (negativeVarColIdx >= 0) {
            doReturn(negativeVarColIdx).when(tableau).columnLabels().indexOf(NEGATIVE_VAR_COLUMN_LABEL);
            if (negativeVarBasicRow != null) {
                doReturn(negativeVarBasicRow).when(tableau).getBasicRow(negativeVarColIdx);
                doReturn(mostNegativeVal).when(tableau).getEntry(negativeVarBasicRow, tableau.getRhsOffset());
            } else {
                doReturn(null).when(tableau).getBasicRow(negativeVarColIdx);
            }
        } else {
            doReturn(-1).when(tableau).columnLabels().indexOf(NEGATIVE_VAR_COLUMN_LABEL);
        }
    }

    @Test
    public void testGetSolution_NoNegativeVar() throws Exception {
        // Setup: No negative variable column found
        doReturn(java.util.Arrays.asList("x0", "x1", RHS_COLUMN_LABEL)).when(tableau).getColumnLabels();
        doReturn(-1).when(tableau).columnLabels().indexOf(NEGATIVE_VAR_COLUMN_LABEL);
        doReturn(2).when(tableau).getOriginalNumDecisionVariables();
        doReturn(0).when(tableau).getRhsOffset();
        doReturn(false).when(tableau).isRestrictToNonNegative();

        // x0 is basic in row 1, x1 is not basic
        doReturn(1).when(tableau).getBasicRow(0); // x0
        doReturn(null).when(tableau).getBasicRow(1); // x1
        doReturn(10.0).when(tableau).getEntry(1, 0); // x0 value is 10

        // Objective function f(x) = 1*x0 + 2*x1
        org.apache.commons.math3.optim.nonlinear.scalar.ObjectiveFunction f = org.apache.commons.math3.optim.nonlinear.scalar.ObjectiveFunction.Builder.create(coeffs -> coeffs[0] + 2 * coeffs[1]);
        // Note: SimplexTableau uses an internal 'f'. Since we can't easily mock the internal 'f' field 
        // without reflection or if it's provided via constructor, we assume the environment allows it.
        // For this test, we assume the method calls f.getValue(coefficients).
        // We will mock the tableau to return a mock objective function.
        org.apache.commons.math3.optim.nonlinear.scalar.MultivariateFunction mockF = mock(org.apache.commons.math3.optim.nonlinear.scalar.MultivariateFunction.class);
        // In a real scenario, we'd use reflection to set the 'f' field if it's private.
        // Here we simulate the logic.

        // We need to bypass the actual 'f.getValue' call. 
        // Since 'f' is a field in SimplexTableau, we use reflection to inject a mock.
        java.lang.reflect.Field fField = SimplexTableau.class.getDeclaredField("f");
        fField.setAccessible(true);
        fField.set(tableau, mockF);
        when(mockF.getValue(any(double[].class))).thenReturn(10.0);

        PointValuePair result = tableau.getSolution();

        assertArrayEquals(new double[]{10.0, 0.0}, result.getPoint(), 1e-9);
        assertEquals(10.0, result.getValue(), 1e-9);
    }

    @Test
    public void testGetSolution_WithNegativeVarAndNonRestrict() throws Exception {
        // Setup: Negative variable exists, restrictToNonNegative = false
        doReturn(java.util.Arrays.asList("x0", NEGATIVE_VAR_COLUMN_LABEL, RHS_COLUMN_LABEL)).when(tableau).getColumnLabels();
        doReturn(1).when(tableau).columnLabels().indexOf(NEGATIVE_VAR_COLUMN_LABEL);
        doReturn(2).when(tableau).getBasicRow(1); // Negative var is in row 2
        doReturn(0).when(tableau).getRhsOffset();
        doReturn(5.0).when(tableau).getEntry(2, 0); // mostNegative = 5.0

        doReturn(1).when(tableau).getOriginalNumDecisionVariables();
        doReturn(false).when(tableau).isRestrictToNonNegative();

        // x0 is basic in row 3
        doReturn(3).when(tableau).getBasicRow(0);
        doReturn(20.0).when(tableau).getEntry(3, 0);

        java.lang.reflect.Field fField = SimplexTableau.class.getDeclaredField("f");
        fField.setAccessible(true);
        org.apache.commons.math3.optim.nonlinear.scalar.MultivariateFunction mockF = mock(org.apache.commons.math3.optim.nonlinear.scalar.MultivariateFunction.class);
        fField.set(tableau, mockF);
        when(mockF.getValue(any(double[].class))).thenReturn(15.0);

        // coefficients[0] = getEntry(3, 0) - mostNegative = 20.0 - 5.0 = 15.0
        PointValuePair result = tableau.getSolution();

        assertArrayEquals(new double[]{15.0}, result.getPoint(), 1e-9);
    }

    @Test
    public void testGetSolution_UnconstrainedVariableInObjective() throws Exception {
        // Setup: x0 is in objective function (basicRow == 0)
        doReturn(java.util.Arrays.asList("x0", RHS_COLUMN_LABEL)).when(tableau).getColumnLabels();
        doReturn(-1).when(tableau).columnLabels().indexOf(NEGATIVE_VAR_COLUMN_LABEL);
        doReturn(1).when(tableau).getOriginalNumDecisionVariables();
        doReturn(0).when(tableau).getRhsOffset();
        doReturn(false).when(tableau).isRestrictToNonNegative();

        doReturn(0).when(tableau).getBasicRow(0); // Objective row

        java.lang.reflect.Field fField = SimplexTableau.class.getDeclaredField("f");
        fField.setAccessible(true);
        org.apache.commons.math3.optim.nonlinear.scalar.MultivariateFunction mockF = mock(org.apache.commons.math3.optim.nonlinear.scalar.MultivariateFunction.class);
        fField.set(tableau, mockF);
        when(mockF.getValue(any(double[].class))).thenReturn(0.0);

        PointValuePair result = tableau.getSolution();

        assertArrayEquals(new double[]{0.0}, result.getPoint(), 1e-9);
    }

    @Test
    public void testGetSolution_DuplicateBasicRows() throws Exception {
        // Setup: x0 and x1 both map to the same basic row
        doReturn(java.util.Arrays.asList("x0", "x1", RHS_COLUMN_LABEL)).when(tableau).getColumnLabels();
        doReturn(-1).when(tableau).columnLabels().indexOf(NEGATIVE_VAR_COLUMN_LABEL);
        doReturn(2).when(tableau).getOriginalNumDecisionVariables();
        doReturn(0).when(tableau).getRhsOffset();
        doReturn(false).when(tableau).isRestrictToNonNegative();
        doReturn(10.0).when(tableau).getEntry(5, 0); // mostNegative (if it were set)

        // x0 is basic in row 5
        doReturn(5).when(tableau).getBasicRow(0);
        doReturn(10.0).when(tableau).getEntry(5, 0);
        // x1 is also basic in row 5 (duplicate)
        doReturn(5).when(tableau).getBasicRow(1);

        // To trigger the 'else if (basicRows.contains(basicRow))' branch, 
        // we need mostNegative to be something other than 0.
        // We'll simulate mostNegative by providing a negative var column.
        doReturn(java.util.Arrays.asList("x0", "x1", NEGATIVE_VAR_COLUMN_LABEL, RHS_COLUMN_LABEL)).when(tableau).getColumnLabels();
        doReturn(2).when(tableau).columnLabels().indexOf(NEGATIVE_VAR_COLUMN_LABEL);
        doReturn(6).when(tableau).getBasicRow(2);
        doReturn(5.0).when(tableau).getEntry(6, 0); // mostNegative = 5.0

        java.lang.reflect.Field fField = SimplexTableau.class.getDeclaredField("f");
        fField.setAccessible(true);
        org.apache.commons.math3.optim.nonlinear.scalar.MultivariateFunction mockF = mock(org.apache.commons.math3.optim.nonlinear.scalar.MultivariateFunction.class);
        fField.set(tableau, mockF);
        when(mockF.getValue(any(double[].class))).thenReturn(5.0);

        // x0: basicRow=5, val=10.0. coeff = 10.0 - 5.0 = 5.0
        // x1: basicRow=5 (already in set), coeff = 0 - (not restrict ? 5.0 : 0) = -5.0
        PointValuePair result = tableau.getSolution();

        assertArrayEquals(new double[]{5.0, -5.0}, result.getPoint(), 1e-9);
    }

    @Test
    public void testGetSolution_MissingVariableInLabels() throws Exception {
        // Setup: x1 is missing from column labels
        doReturn(java.util.Arrays.asList("x0", RHS_COLUMN_LABEL)).when(tableau).getColumnLabels();
        doReturn(-1).when(tableau).columnLabels().indexOf(NEGATIVE_VAR_COLUMN_LABEL);
        doReturn(2).when(tableau).getOriginalNumDecisionVariables();
        doReturn(0).when(tableau).getRhsOffset();
        doReturn(false).when(tableau).isRestrictToNonNegative();

        doReturn(1).when(tableau).getBasicRow(0);
        doReturn(10.0).when(tableau).getEntry(1, 0);

        java.lang.reflect.Field fField = SimplexTableau.class.getDeclaredField("f");
        fField.setAccessible(true);
        org.apache.commons.math3.optim.nonlinear.scalar.MultivariateFunction mockF = mock(org.apache.commons.math3.optim.nonlinear.scalar.MultivariateFunction.class);
        fField.set(tableau, mockF);

        PointValuePair result = tableau.getSolution();

        // x0 = 10.0, x1 = 0.0 (because colIndex < 0)
        assertArrayEquals(new double[]{10.0, 0.0}, result.getPoint(), 1e-9);
    }

    @Test
    public void testGetSolution_RestrictToNonNegativeTrue() throws Exception {
        // Setup: restrictToNonNegative = true
        doReturn(java.util.Arrays.asList("x0", NEGATIVE_VAR_COLUMN_LABEL, RHS_COLUMN_LABEL)).when(tableau).getColumnLabels();
        doReturn(1).when(tableau).columnLabels().indexOf(NEGATIVE_VAR_COLUMN_LABEL);
        doReturn(2).when(tableau).getBasicRow(1);
        doReturn(5.0).when(tableau).getEntry(2, 0); // mostNegative = 5.0

        doReturn(1).when(tableau).getOriginalNumDecisionVariables();
        doReturn(true).when(tableau).isRestrictToNonNegative();
        doReturn(0).when(tableau).getRhsOffset();

        doReturn(3).when(tableau).getBasicRow(0);
        doReturn(20.0).when(tableau).getEntry(3, 0);

        java.lang.reflect.Field fField = SimplexTableau.class.getDeclaredField("f");
        fField.setAccessible(true);
        org.apache.commons.math3.optim.nonlinear.scalar.MultivariateFunction mockF = mock(org.apache.commons.math3.optim.nonlinear.scalar.MultivariateFunction.class);
        fField.set(tableau, mockF);

        // coefficients[0] = 20.0 - 0 = 20.0
        PointValuePair result = tableau.getSolution();

        assertArrayEquals(new double[]{20.0}, result.getPoint(), 1e-9);
    }
}
